import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"다가구주택 월세 계약 후기","description":"생애최초 주택임대차계약을 진행하면서 알게 된 정보를 공유합니다.","frontmatter":{"title":"다가구주택 월세 계약 후기","date":"2026-02-03T23:00+09:00","description":"생애최초 주택임대차계약을 진행하면서 알게 된 정보를 공유합니다.","tags":["부동산","임대차계약","다가구주택","월세"]},"headers":[],"relativePath":"sleep/housing-lease-agreement.md","filePath":"sleep/housing-lease-agreement.md","lastUpdated":1784727263000}`),a={name:`sleep/housing-lease-agreement.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="다가구주택-월세-계약-후기" tabindex="-1">다가구주택 월세 계약 후기 <a class="header-anchor" href="#다가구주택-월세-계약-후기" aria-label="Permalink to “다가구주택 월세 계약 후기”">​</a></h1><p>저는 경기도 역세권 <mark>아파트 청약에 당첨되어 분양권을 보유</mark> 하고 있지만 <strong>아파트 입주가 2029년 1월로 예정</strong> 되어 있어서 입주 전까지는 약 3년이라는 생각보다 긴 시간이 남아있는 상황이에요. 결혼을 약속하게 된 여자친구와 함께 살아갈 작은 보금자리가 필요한 상황이 되었어요.</p><p>평소 여자친구의 생활권이라 익숙한 신대방삼거리역 근처로 투룸 매물을 알아보았으나 실제로 매물을 구경하기조차 어려웠어요. 그래서 서울권이 아닌 근교로 범위를 넓혀 찾아보았더니, <mark>광명사거리역 근처의 신축 다가구주택</mark> 을 보게 되었고 결국 계약까지 앞두게 되었어요.</p><p>저는 부동산 계약 경험이 전혀 없었던 입장이라, 이번에 다가구주택에 대한 <mark>주택임대차계약</mark> 을 준비하며 정말 많이 공부하고 알아보게 되었어요. 매물 확인부터 계약 체결까지의 과정 속에서 알게 된 정보들과 다소 아쉬웠던 점들을 바탕으로 공부한 내용을 함께 공유해보고자 해요.</p><h2 id="_1-매물-정보와-계약-조건" tabindex="-1">1. 매물 정보와 계약 조건 <a class="header-anchor" href="#_1-매물-정보와-계약-조건" aria-label="Permalink to “1. 매물 정보와 계약 조건”">​</a></h2><p>제가 계약하려는 매물은 <strong>광명7R 공공재개발구역</strong> 내에 위치한 신축 다가구주택이에요.</p><ul><li><strong>건물 개요</strong>: 2021년 준공, 내부 컨디션 최상, 외부 주차 가능</li><li><strong>유형</strong>: 다가구주택 (6가구)</li><li><strong>보증금 / 월세</strong>: <strong>5,000만 원 / 약 100만 원</strong></li><li><strong>특이사항</strong>: <ol><li><strong>주인 거주</strong>: 건물주(명의자) 5층 실거주</li><li><strong>근저당</strong>: 토지·건물 공동담보, <strong>채권최고액 6억 원</strong> 설정</li><li><strong>재개발</strong>: 사업시행인가 및 관리처분계획인가 단계 예정</li></ol></li></ul><h2 id="_2-전세보다-준월세" tabindex="-1">2. 전세보다 준월세 <a class="header-anchor" href="#_2-전세보다-준월세" aria-label="Permalink to “2. 전세보다 준월세”">​</a></h2><p><a href="https://n.news.naver.com/article/366/0001137337" target="_blank" rel="noreferrer">전세는 없고, 월세는 비싸고… 서울 임대차 55%는 ‘준월세’</a> 라는 뉴스처럼 준월세 매물의 비중이 커지고 있어요. 계약하려는 집도 서울 지역은 아니지만 보증금 5,000만 원에 월세(차임) 100만 원, 관리비 10만 원으로 생각보다 월 주거비가 높았어요. 애초에 저희가 준월세를 고려한 이유는 전세 보증금을 가지고 있어도 향후 신축 아파트를 입주하려는 시기에 <mark>자금 흐름이 애매해질 수 있겠다</mark> 는 우려사항 때문이었어요.</p><blockquote><p>여자친구의 지인이 전세사기를 당했던 경험이 있어서 그에 대한 걱정도 일부 있었어요. 최우선변제라는 법이 있어도 즉시 받는 게 아니라 경매로 넘어갔을 때 받기까지는 수개월이 걸릴 수 있어요.</p></blockquote><p>그런데 가계약 단계에서는 몰랐었지만, <strong>임대차계약에서 다가구주택은 굉장히 위험한 매물</strong> 이라고 해요. 다가구주택은 여러 가구가 거주하는 주택으로, 토지와 건물이 1인 소유이면서 다른 세입자들에 대한 선순위 보증금 현황을 알 수 없다는 구조적인 문제가 있다고 해요. 심지어는 계약하기 전에 <mark>확정일자 보유현황</mark> 을 열람하려면 <strong>임대인의 동의가 필요</strong> 해요. 이러한 상황에서도 최근 대법원은 <a href="https://www.yna.co.kr/view/AKR20260112145400004" target="_blank" rel="noreferrer">임대인이 자료 안줘도 중개사는 선순위채권 설명해야</a> 한다고는 해요.</p><h2 id="_3-최우선변제권" tabindex="-1">3. 최우선변제권 <a class="header-anchor" href="#_3-최우선변제권" aria-label="Permalink to “3. 최우선변제권”">​</a></h2><p>최우선변제권은 주택임대차보호법에 의거하여 보증금이 일정 금액 이하인 소액임차인에 해당되면 <strong>주택이 경매에 넘어가도</strong> 선순위 채권인 근저당보다 우선하여 변제받을 수 있는 권리예요. 전입신고로 대항력을 가지게 되면 <mark>근저당 설정일 기준</mark> 최우선변제 금액 한도만큼 먼저 배당받을 수 있어요.</p><p>최우선변제 금액에서 가장 중요한 건 <strong>계약 시점</strong> 이 아니라 해당 주택의 <strong>근저당 설정일</strong> 인데요. 이 건물의 근저당 설정일은 <mark>2022년 3월</mark> 이기 때문에 당시 시행 중이던 법령을 따라야 해요.</p><h3 id="광명시-최우선변제-기준-2022-03-근저당-기준" tabindex="-1">광명시 최우선변제 기준 (2022.03 근저당 기준) <a class="header-anchor" href="#광명시-최우선변제-기준-2022-03-근저당-기준" aria-label="Permalink to “광명시 최우선변제 기준 (2022.03 근저당 기준)”">​</a></h3><p>광명시는 당시에도 <strong>과밀억제권역</strong> 에 해당해요.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">소액임차인 인정 범위 (보증금)</th><th style="text-align:left;">최우선변제금 (보장 금액)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>과밀억제권역</strong></td><td style="text-align:left;"><strong>1억 3,000만 원 이하</strong></td><td style="text-align:left;"><strong>최대 4,300만 원</strong></td></tr></tbody></table><p><strong>분석 결과</strong>:</p><ul><li>저의 보증금은 <strong>5,000만 원</strong> 이므로 <strong>1억 3,000만 원 이하</strong> 조건에 부합하여 <strong>소액임차인</strong> 에 해당해요.</li><li>선순위채권(근저당)보다 먼저 <strong>4,300만 원</strong> 을 <mark>최우선변제 가능</mark> 해요.</li><li>선순위 보증금으로 인해 <strong>700만 원</strong> 가량의 <mark>손실 위험</mark> 이 존재해요.</li></ul><p>서울 지역 기준의 최우선변제 금액 기준만 알았기에 보증금 전액이 보호될 줄 알았어요. 하지만 가계약 이후에 확인해 본 결과, <mark>근저당 설정일 기준으로 4,300만 원까지 보호</mark> 되고 700만 원은 보호받지 못한다는 사실을 알게 되었어요.</p><blockquote><p>심지어 본 계약 시 공인중개사는 광명시 주택인데도 불구하고 서울 소재지의 최우선변제 금액을 기준으로 안전하다고 설명했어요.</p></blockquote><p>따라서 최우선변제 금액을 제외한 나머지는 돌려받지 못할 수도 있다는 점을 명확히 인지하고 계약해야 해요.</p><h3 id="최우선변제금을-보장하지-못하는-상황" tabindex="-1">최우선변제금을 보장하지 못하는 상황 <a class="header-anchor" href="#최우선변제금을-보장하지-못하는-상황" aria-label="Permalink to “최우선변제금을 보장하지 못하는 상황”">​</a></h3><p>한 가지 알아두어야 할 점은, 최악의 상황을 가정해서 최우선변제 금액보다 낙찰가가 낮은 경우 <mark>최우선변제금이 전액 보장되지 않을 가능성도 있다</mark> 는 것이에요. 주택임대차보호법에 따라 <strong>최우선변제금의 합계액은 주택가액(경매 낙찰가)의 2분의 1을 초과할 수 없습니다.</strong> 즉, 낙찰가의 <strong>2분의 1</strong> 을 소액임차인들이 나누어 배당(<strong>안분배당</strong>)을 받게 돼요.</p><blockquote><p>공인중개사에게 설명을 듣지 못한 부분이라 개인적으로 찾아보다가 알게 되었어요.</p></blockquote><h2 id="_4-확정일자-보유현황" tabindex="-1">4. 확정일자 보유현황 <a class="header-anchor" href="#_4-확정일자-보유현황" aria-label="Permalink to “4. 확정일자 보유현황”">​</a></h2><p>월세 계약을 진행하려는 소액임차인이어도 다가구주택에서 선순위 세입자 보증금을 대략적으로나마 알아두는 건 중요해요. 본 계약 이전에 확정일자 보유현황을 요청해서 <mark>소액임차인 규모를 확인</mark> 했어요.</p><h2 id="_5-월세보증보험" tabindex="-1">5. 월세보증보험 <a class="header-anchor" href="#_5-월세보증보험" aria-label="Permalink to “5. 월세보증보험”">​</a></h2><p>해당 매물은 <strong>사업시행인가 단계를 앞두고 있는 재개발 구역</strong> 에 위치해 있다 보니 조금 불안한 마음에 혹시나 월세보증보험에 가입할 수 있는지 알아보았어요. 하지만 현실적으로 다가구주택은 보증보험 가입이 매우 어려운 구조였는데요. 우선 해당 매물에 대출(근저당)이 아예 없어야만 가입이 가능한 수준이었어요.</p><h3 id="다가구주택의-개별단독주택가격" tabindex="-1">다가구주택의 개별단독주택가격 <a class="header-anchor" href="#다가구주택의-개별단독주택가격" aria-label="Permalink to “다가구주택의 개별단독주택가격”">​</a></h3><p>중개인과 함께 매물을 확인하러 갔을 때는 중개사무소에서 생각하는 감정평가액은 <strong>24억~28억 원</strong> 으로 안전한 매물이라고 안내했지만, 보증보험 가입 가능 여부를 확인하기 위해서 공시된 <a href="https://www.realtyprice.kr/notice/hpindividual/search.htm" target="_blank" rel="noreferrer">개별단독주택가격</a> 을 확인해보니 <strong>6억 8,400만 원(2025년 기준)</strong> 에 불과했어요.</p><p>다가구주택은 아파트와 달리 KB시세나 한국부동산원 시세가 없기 때문에, 보증기관에서는 <strong>공시된 개별단독주택가격</strong> 을 기준으로 주택가격을 산정하게 되는데요.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">주택가격 산정 기준 (다가구주택)</th><th style="text-align:left;">주택가격 (<strong>6.84억</strong> 기준)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>HUG</strong> (주택도시보증공사)</td><td style="text-align:left;">개별단독주택가격 × <strong>140%</strong></td><td style="text-align:left;"><strong>9억 5,760만 원</strong></td></tr><tr><td style="text-align:left;"><strong>SGI</strong> (서울보증보험)</td><td style="text-align:left;">개별단독주택가격 × <strong>130%</strong></td><td style="text-align:left;"><strong>8억 8,920만 원</strong></td></tr></tbody></table><p>이처럼 공시가격에 일정 비율을 반영하더라도 실제 감정평가액과는 괴리가 매우 커요.</p><h3 id="가입-심사-기준" tabindex="-1">가입 심사 기준 <a class="header-anchor" href="#가입-심사-기준" aria-label="Permalink to “가입 심사 기준”">​</a></h3><p>보증보험 가입을 위해서는 <strong>보증한도(주택가격 × 담보인정비율 90% - 선순위채권 등)</strong> 내에 전세보증금이 들어와야 해요. 또한, 다음과 같은 까다로운 조건들을 모두 충족해야 해요.</p><ol><li><strong>선순위채권(근저당)이 주택가액의 60% 이내</strong> 여야 해요.</li><li><strong>주택의 건물 및 토지(대지권)가 모두 임대인의 소유</strong> 여야 해요.</li><li><strong>선순위채권 + 선순위 보증금액 합계가 주택가액의 80% 이내</strong> 여야 해요. <ul><li>선순위 보증금액에는 후순위 및 공실의 최우선변제금도 포함돼요.</li><li>주택가액 = 주택가격 × 담보인정비율(90%)</li></ul></li><li><strong>타 전세계약체결내역 확인서(공사양식) 상 가구수와 건축물대장 상 가구수가 일치</strong> 해야 해요.</li></ol><p>여기서 중요한 부분은 <strong>선순위채권</strong> 은 등기부등본의 근저당 채권최고액 뿐만 아니라 나보다 먼저 전입하고 있는 다른 세입자들의 선순위 보증금의 합계를 모두 포함해야 한다는 점이에요.</p><p>해당 건물의 경우 <strong>HUG 기준 주택가격은 9억 5,760만 원</strong> 이에요. 여기에 담보인정비율 90%를 곱한 <strong>주택가액은 약 8억 6,184만 원</strong> 이에요. 이를 토대로 심사 기준을 대입해보면 다음과 같이 모든 조건에서 가입 기준을 만족하지 못하게 돼요.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">기준 한도</th><th style="text-align:left;">실제 해당 금액</th><th style="text-align:left;">결과</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>선순위채권 60%</strong></td><td style="text-align:left;"><strong>5억 1,710만 원</strong> (주택가액의 60%)</td><td style="text-align:left;">6억 원</td><td style="text-align:left;"><strong>부적격</strong></td></tr><tr><td style="text-align:left;"><strong>부채비율 80%</strong></td><td style="text-align:left;"><strong>6억 8,947만 원</strong> (주택가액의 80%)</td><td style="text-align:left;">11억 2,000만 원</td><td style="text-align:left;"><strong>부적격</strong></td></tr></tbody></table><p>주택도시보증공사에서 제공하는 <a href="https://khig.khug.or.kr/websquare/popup.html?w2xPath=/cg/ae/CGAE034P02.xml" target="_blank" rel="noreferrer">보증가능여부 간편확인</a> 서비스를 이용했을 때 <strong>가입 불가</strong> 판정이 나오므로 HUG 보증보험 가입은 불가능해요.</p><h3 id="sgi서울보증-이라면" tabindex="-1">SGI서울보증 이라면? <a class="header-anchor" href="#sgi서울보증-이라면" aria-label="Permalink to “SGI서울보증 이라면?”">​</a></h3><p>SGI의 주택담보대출비율(LTV) 계산식은 <code>(임차보증금 + 선순위채권 등) ÷ 주택가격</code> 이에요.</p><ul><li><strong>담보설정액</strong>: 내 보증금(5천) + 근저당(6억) + 선순위보증금(5.2억) = <strong>11억 7,000만 원</strong></li><li><strong>주택가격</strong>: 개별단독주택가격(6.84억) × 130% = <strong>8억 8,920만 원</strong></li></ul><p>계산 결과 <strong>LTV가 약 131.5%</strong> 로 가입 기준인 <strong>100% 이내</strong> 를 초과하여 가입이 불가능해요. 다만 개별단독주택가격 대신 <strong>공인중개사 시세 확인서</strong> 를 제출하여 주택가격을 시세에 가깝게 인정받을 수도 있겠지만, 이 역시 임대인의 적극적인 서류 협조가 없으면 어려워요.</p><h3 id="보증보험-가입을-위한-임대인의-협조" tabindex="-1">보증보험 가입을 위한 임대인의 협조 <a class="header-anchor" href="#보증보험-가입을-위한-임대인의-협조" aria-label="Permalink to “보증보험 가입을 위한 임대인의 협조”">​</a></h3><p>주택가격 기준에 해당되더라도 <strong>다가구주택의 경우 임대인의 서류 협조가 필수적</strong> 이에요. 보증회사별로 다음의 서류들을 임대인에게 요청해야 하거든요.</p><ul><li><strong>HUG</strong>: 타전세계약체결내역확인서, 확정일자부여현황</li><li><strong>SGI서울보증</strong>: 임대차사실확인서, 전입세대열람원, 확정일자부여현황</li></ul><p>즉 임대인의 협조가 없다면 보증보험 가입은 애초에 불가능해요. 따라서 <strong>보증보험 가입을 위한 임대인의 협조를 특약으로 넣을 필요가 없고</strong> 본 계약 시 구두로 전달받은 선순위 보증금이 맞는지 <mark>확정일자 부여현황</mark> 을 확인해보는 것으로 갈무리하려 해요.</p><h2 id="_6-계약-시-확인사항" tabindex="-1">6. 계약 시 확인사항 <a class="header-anchor" href="#_6-계약-시-확인사항" aria-label="Permalink to “6. 계약 시 확인사항”">​</a></h2><p>계약 당일, 다음의 서류들을 반드시 발급받아 확인해야 해요.</p><ol><li><strong>등기부등본 (건물 + 토지)</strong>: 소유자 및 근저당 설정 내역 확인 (계약금 입금 직전 발급분)</li><li><strong>건축물대장</strong>: 위반건축물 등재 여부 및 호수 일치 여부</li><li><strong>확정일자 부여현황</strong>: 선순위 임차인 보증금 및 소액임차인 현황 재확인</li><li><strong>납세증명서 (국세) &amp; 지방세 납세증명서</strong>: 임대인의 세금 체납 여부 확인</li></ol><p>부동산 계약에서 <strong>건축물대장</strong> 과 <strong>등기부등본</strong> 은 법적으로 임차인을 보장해주지 않는다고 해요. 그래서 대부분 임차인이 보장받고자 하는 부분은 <strong>특약 사항</strong> 으로 명시해야 해요.</p><h3 id="특약-사항" tabindex="-1">특약 사항 <a class="header-anchor" href="#특약-사항" aria-label="Permalink to “특약 사항”">​</a></h3><ul><li>임대인은 현 등기부등본 상태를 임차인이 대항력을 갖추게 되는 날의 다음 영업일까지 유지하기로 한다.</li><li>본 계약 기간 중 본 주택에 대하여 근저당권 설정, 가압류, 가처분, 담보 제공 등 일체의 권리 변동 행위를 하지 않는다.</li><li>입·퇴실 청소비는 없으며 퇴실 시 원상복구 한다.</li></ul><blockquote><p>첫 번째 특약과 두 번째 특약은 사실상 같은 의미예요.</p></blockquote><h3 id="국세-및-지방세-체납-확인-불가" tabindex="-1">국세 및 지방세 체납 확인 불가 <a class="header-anchor" href="#국세-및-지방세-체납-확인-불가" aria-label="Permalink to “국세 및 지방세 체납 확인 불가”">​</a></h3><p>공인중개사는 임대인의 국세 및 지방세 완납 증명서를 필수적으로 확인해줄 의무는 없어요. 그러므로 임차인은 임대차 계약 체결 전에 임대인에게 <mark>국세 및 지방세 완납 증명서를 미리 요구해야</mark> 해요. 저는 사전에 요구하지 못해서 대리인을 통해 계약을 진행하는 과정에서 확인하지 못했고, 공인중개사가 계약 체결 이후에 확인을 해주거나 계약을 체결한 임차인 입장에서 임대인 동의 없이 직접 열람해야 하는 상황이 되었어요.</p><p>물론 2023년 4월에 개정된 법령에 따라 <strong>보증금 1,000만 원을 초과</strong> 하는 임대차 계약을 체결한 임차인은 <strong>임대인의 동의 없이도</strong> 직접 미납 세금을 열람할 수 있어요. 다만 인터넷으로 신청하더라도 실제 열람은 주민센터(지방세)와 세무서(국세)를 직접 방문해야 하고, <strong>참고</strong> 로 임차인이 미납 국세/지방세를 열람할 경우 관련 법령에 따라 <strong>열람 사실이 임대인에게 통보돼요.</strong></p><p>그래서 번거롭더라도 입주 전(잔금 입금 전)에 <strong>안심전세 앱</strong> 을 통해 임대인의 국세 및 지방세 체납 내역을 조회하면 좋아요. 주택임대차계약 신고가 완료되고 확정일자가 부여되었다면 안심전세 앱에서 임대인의 국세 및 지방세 체납 내역을 열람할 수 있어요.</p><h2 id="_7-주택-임대차계약-신고" tabindex="-1">7. 주택 임대차계약 신고 <a class="header-anchor" href="#_7-주택-임대차계약-신고" aria-label="Permalink to “7. 주택 임대차계약 신고”">​</a></h2><p>2025년 6월부터 <mark>보증금 6천만 원 또는 월차임 30만 원 초과</mark> 에 대한 <a href="https://www.youtube.com/watch?v=veiXWtt2IWQ" target="_blank" rel="noreferrer">주택 임대차계약 신고가 의무화</a> 되었어요. 가계약금 입금 시 중개법인을 통해 계약에 대한 내용을 명시하였기 때문에 <a href="https://youtu.be/FAN6ECKzo3M?si=xMcuvfh_voPuBD__" target="_blank" rel="noreferrer">가계약 입금일 기준으로 계약 체결일</a> 로 간주하여 신고해야 한다고 생각했는데, 임대차계약서 상 계약 체결일을 기준으로 신고하면 된다고 하네요.</p><h2 id="_8-임대차계약서-오타-및-오기재" tabindex="-1">8. 임대차계약서 오타 및 오기재 <a class="header-anchor" href="#_8-임대차계약서-오타-및-오기재" aria-label="Permalink to “8. 임대차계약서 오타 및 오기재”">​</a></h2><p>저는 기본적인 부분은 <mark>공인중개사가 알아서 해주겠지</mark> 라는 생각을 했는데, 임대차계약서에 오타 또는 잘못된 부분이 많았어요. 저는 계약 체결 후 즉시 <a href="https://rtms.molit.go.kr/main/main.do" target="_blank" rel="noreferrer">임대차계약 신고</a> 를 했는데 임차인 연락처가 잘못 기재되었음을 뒤늦게 발견하고 주민센터에서 반려되어 계약서를 다시 작성해야만 했어요.</p><p>임대차계약서에서 제대로 신경 쓰지 못한 부분은 다음과 같아요.</p><ul><li>임대차계약서를 복사하는 과정에서 <mark>임차인 연락처</mark> 를 변경하지 않았어요.</li><li>임대인 서명에 <mark>대리인 도장 날인 시</mark> 대리인의 인적사항이 포함되지 않고 누락되었어요.</li><li>공인중개사무소 주소가 현재와 맞지 않았어요.</li></ul><p>주민센터에 따르면, 임대차계약 신고 시 계약서 상 임차인 연락처로 통지간다고 하네요.</p><h2 id="_9-입주-준비" tabindex="-1">9. 입주 준비 <a class="header-anchor" href="#_9-입주-준비" aria-label="Permalink to “9. 입주 준비”">​</a></h2><p>입주 전후로 반드시 챙겨야 할 사항들을 정리했어요.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">할 일</th><th style="text-align:left;">시기</th><th style="text-align:left;">참고사항</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>입주청소</strong></td><td style="text-align:left;">셀프 청소 진행</td><td style="text-align:left;">이사 당일부터 2일간</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><strong>도시가스</strong></td><td style="text-align:left;">전입 신청 및 기사 방문 예약</td><td style="text-align:left;">입주 2~3일 전</td><td style="text-align:left;"><strong>삼천리도시가스</strong> 사전 예약 필수</td></tr><tr><td style="text-align:left;"><strong>전기</strong></td><td style="text-align:left;">전입 신청 (명의 변경)</td><td style="text-align:left;">입주 당일</td><td style="text-align:left;"><strong>한전ON</strong> 온라인 신청</td></tr><tr><td style="text-align:left;"><strong>수도</strong></td><td style="text-align:left;">전입 신청 (명의 변경)</td><td style="text-align:left;">입주 당일</td><td style="text-align:left;"><strong>광명시청 수도과</strong></td></tr><tr><td style="text-align:left;"><strong>전입신고</strong></td><td style="text-align:left;">정부24</td><td style="text-align:left;"><strong>입주 당일 즉시</strong></td><td style="text-align:left;"><mark>대항력 확보</mark></td></tr><tr><td style="text-align:left;"><strong>주소변경</strong></td><td style="text-align:left;">우편물 주소 이전</td><td style="text-align:left;">입주 후</td><td style="text-align:left;">금융, 통신사 등</td></tr></tbody></table><p>참고로, 정부24의 <strong>주민등록 관련 통보서비스</strong> 를 신청하면 전입신고 사실을 임대인에게 통보할 수 있어요.</p>`,71)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};